{% # theme-check-disable %}
<script src="{{ 'predictive-search.js' | asset_url }}" defer="defer"></script>
<predictive-search class="predictive-search" data-results-count="{{ results_count }}">
  <p class="predictive-search__status" role="status">
    {%- if results_count > 0 -%}
      {{ 'templates.search.results_with_count' | t: count: results_count }}
    {%- else -%}
      {{ 'templates.search.no_results' | t }}
    {%- endif -%}
  </p>
  <div class="predictive-search__loading" hidden>
    {%- render 'loading-spinner' -%}
  </div>
</predictive-search>
